import{_ as t}from"./chunks/architecture-layers.Z-RS_8yM.js";import{_ as e,o,c as r,a2 as s}from"./chunks/framework.BqDA2HS7.js";const f=JSON.parse('{"title":"项目简介","description":"","frontmatter":{"title":"项目简介"},"headers":[],"relativePath":"index.md","filePath":"index.md"}'),i={name:"index.md"};function n(l,a,c,d,h,p){return o(),r("div",null,[...a[0]||(a[0]=[s('<div class="doc-kicker">REFRACTROUTER · 析衡</div><h1 id="让团队的模型-按任务各尽其用" tabindex="-1">让团队的模型，按任务各尽其用 <a class="header-anchor" href="#让团队的模型-按任务各尽其用" aria-label="Permalink to &quot;让团队的模型，按任务各尽其用&quot;">​</a></h1><p class="doc-intro">RefractRouter 面向小型开发团队提供独立模型路由：先满足可接受的质量，再降低模型总成本，最后减少响应与等待时间。</p><div class="doc-badges"><span class="doc-badge">独立 Python 核心</span><span class="doc-badge">DSH / Codex CLI</span><span class="doc-badge">开发预览</span></div><p>你可以继续使用已有的 Ark、Kimi、DeepSeek 或其他已适配模型服务。Router 根据策略选择 实际模型，记录判别、接受与丢弃、调用费用及运行原因。模型提供方的凭证由你自己配置。</p><h2 id="两种路由" tabindex="-1">两种路由 <a class="header-anchor" href="#两种路由" aria-label="Permalink to &quot;两种路由&quot;">​</a></h2><div class="doc-route-links"><a class="doc-route-link" href="/RefractRouter/planning.html"><strong>规划路由</strong><span>保留 Agent 原生执行循环。使用 Static、Stage、Task、Composite、Advisor Gate 或 Escalation 选择模型、审核和接管。</span></a><a class="doc-route-link" href="/RefractRouter/automatic.html"><strong>自动路由</strong><span>判断整任务 Direct 与任务 DAG 的适用性；必要时规划节点、分配模型、并行调用和汇总。保留为独立研究入口。</span></a></div><p>“规划”在这里指<strong>模型调用策略</strong>，不会把你的任务拆成 DAG。“自动”也不表示每次都拆分： 即使任务可以拆分，Router 仍可能选择 Direct。详见<a href="./routing.html">两种路由怎么选</a>。</p><h2 id="python-核心与-dsh-插件" tabindex="-1">Python 核心与 DSH 插件 <a class="header-anchor" href="#python-核心与-dsh-插件" aria-label="Permalink to &quot;Python 核心与 DSH 插件&quot;">​</a></h2><figure class="doc-diagram"><img src="'+t+'" alt="四层架构：宿主 Agent、DSH 插件或标准网关、Python 核心、模型服务"><figcaption>策略、准入、账本与证据只在 Python 核心实现一次；插件与网关是两种接入方式。</figcaption></figure><p>很多人第一次接触会以为 DSH 插件就是 RefractRouter。实际上插件只是宿主适配层： 它把 DSH 的请求转给独立的 Python 核心，核心决定用哪个模型、如何审核、怎么记账， 插件再把结果和轨迹展示出来。Codex CLI 走的是另一条路：标准模型网关按 Base URL 接入，不装插件。两条路最终调用的是同一套 Python 策略实现。</p><p>分层细节、模块速查和语言边界见<a href="./architecture.html">架构</a>。</p><h2 id="适用场景" tabindex="-1">适用场景 <a class="header-anchor" href="#适用场景" aria-label="Permalink to &quot;适用场景&quot;">​</a></h2><ul><li><strong>代码任务</strong>：由 Agent 读写文件、运行测试，Stage 根据可信执行证据切换模型。</li><li><strong>研究与写作</strong>：Task 在任务开始时选择主模型；Advisor 对最终候选进行审核。</li><li><strong>成本受控的探索</strong>：Escalation 先使用起始模型，必要时由指定接管模型接手。</li><li><strong>独立子问题研究</strong>：通过自动路由尝试 DAG；同时核对规划、汇总和审核的额外开销。</li></ul><h2 id="从哪里开始" tabindex="-1">从哪里开始 <a class="header-anchor" href="#从哪里开始" aria-label="Permalink to &quot;从哪里开始&quot;">​</a></h2><ol><li><a href="./installation.html">下载安装</a>：下载 wheel 与插件包，保留已有 DSH profile。</li><li><a href="./quickstart.html">第一项任务</a>：先用 Static 验证真实模型与工具接线。</li><li><a href="./strategies/">六种策略</a>：了解各自的选模、审核和接管行为。</li><li><a href="./traces.html">运行记录</a>：检查实际模型、图形、执行时间、费用和失败原因。</li></ol><div class="tip custom-block"><p class="custom-block-title">目标与证据分开看</p><p>降低成本和等待时间是产品目标。目前没有证据证明所有策略或 DAG 在开放任务上普遍优于 固定模型。Judge 的概率与分数也不是任务成功率。请结合<a href="./status.html">验证范围</a>判断是否适合你的工作。</p></div>',17)])])}const m=e(i,[["render",n]]);export{f as __pageData,m as default};
